// TEMPORARY PRIVATE STAGING TEST ONLY. Remove after the authorized debug test.
// The token is generated by the Firebase SDK and kept only in browser-local state and Firebase staging registration.
declare const __VERCEL_ENV__: string;
declare const __VERCEL_GIT_COMMIT_REF__: string;

const exactStagingOrigin = 'https://arcrm-app-git-cue-firebase-stabilization-anggaramadhan538-8607.vercel.app';
const registrationReadyKey = 'arcrm:private-staging-app-check:registration-ready';
const debugTokenStorageKey = 'arcrm:private-staging-app-check:debug-token';
const debugTokenLogPrefix = 'Firebase App Check debug token: ';

export const privateStagingPreviewDebug = !import.meta.env.DEV
  && typeof window !== 'undefined'
  && window.location.origin === exactStagingOrigin
  && typeof __VERCEL_ENV__ !== 'undefined'
  && __VERCEL_ENV__ === 'preview'
  && typeof __VERCEL_GIT_COMMIT_REF__ !== 'undefined'
  && __VERCEL_GIT_COMMIT_REF__ === 'cue/firebase-stabilization';

if (privateStagingPreviewDebug) {
  const firebaseGlobals = globalThis as typeof globalThis & { FIREBASE_APPCHECK_DEBUG_TOKEN?: boolean };
  firebaseGlobals.FIREBASE_APPCHECK_DEBUG_TOKEN = true;

  // The SDK normally prints the debug token to console. Capture it locally instead.
  const originalConsoleLog = console.log;
  console.log = (...args: unknown[]) => {
    const first = args[0];
    if (typeof first === 'string' && first.startsWith(debugTokenLogPrefix)) {
      const token = first.slice(debugTokenLogPrefix.length).trim();
      if (token.length >= 24 && token.length <= 512) {
        try { window.sessionStorage.setItem(debugTokenStorageKey, token); } catch { /* fail closed */ }
      }
      console.log = originalConsoleLog;
      return;
    }
    originalConsoleLog.apply(console, args);
  };

  const privateBridge = globalThis as typeof globalThis & {
    __arcrmMarkStagingDebugRegistrationReady?: () => boolean;
    __arcrmClearStagingDebugLocalState?: () => Promise<boolean>;
  };
  privateBridge.__arcrmMarkStagingDebugRegistrationReady = () => {
    try {
      window.sessionStorage.setItem(registrationReadyKey, 'registered');
      return true;
    } catch {
      return false;
    }
  };
  privateBridge.__arcrmClearStagingDebugLocalState = async () => {
    try {
      window.sessionStorage.removeItem(registrationReadyKey);
      window.sessionStorage.removeItem(debugTokenStorageKey);
    } catch {
      return false;
    }
    const firebaseAppId = import.meta.env.VITE_FIREBASE_APP_ID?.trim();
    return new Promise<boolean>((resolve) => {
      try {
        const request = indexedDB.open('firebase-app-check-database', 1);
        request.onerror = () => resolve(false);
        request.onsuccess = () => {
          const database = request.result;
          if (!database.objectStoreNames.contains('firebase-app-check-store')) {
            database.close();
            resolve(true);
            return;
          }
          const transaction = database.transaction('firebase-app-check-store', 'readwrite');
          const store = transaction.objectStore('firebase-app-check-store');
          store.delete('debug-token');
          if (firebaseAppId) store.delete(`${firebaseAppId}-[DEFAULT]`);
          transaction.oncomplete = () => { database.close(); resolve(true); };
          transaction.onerror = () => { database.close(); resolve(false); };
          transaction.onabort = () => { database.close(); resolve(false); };
        };
      } catch {
        resolve(false);
      }
    });
  };
}

/** Non-secret browser-local pause; set only after staging Console registration is verified. */
export function privateStagingDebugRegistrationReady(): boolean {
  if (!privateStagingPreviewDebug) return false;
  try {
    return window.sessionStorage.getItem(registrationReadyKey) === 'registered';
  } catch {
    return false;
  }
}
